<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    pg_size_pretty(pg_database_size(datname)) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> db_size</span></span>
